INSERT INTO "zing_doctor_db_prod"."quality_def_history" ("id", "def_type", "def_key", "expr_version", "change_type", "snapshot", "operator", "create_time") VALUES (178955617523600, 'FACT', 'fact_patient_stay', NULL, 'UPDATE', '{"fact":"fact_patient_stay","domain":"患者流转","status":"ACTIVE","source":"patient_info","alias":"pi","patientKey":"patient_id","inHospitalNoKey":"in_hospital_no","patientNameKey":"patient_name","departKey":"depart_code","select":["pi.id AS patient_id","pi.in_hospital_no AS in_hospital_no","pi.name AS patient_name","pi.gender AS gender","pi.age AS age","pi.depart_code AS depart_code","pi.ward_name AS ward_name","pi.out_vest_type AS out_vest_type","pi.charge_doctor_name AS charge_doctor_name","pi.in_depart_time AS in_depart_time","pi.out_depart_time AS out_depart_time","pi.out_hospital_time AS out_hospital_time","pi.diagnosis_content AS diagnosis_content"],"derive":["CASE WHEN pi.in_depart_time >= :periodStart THEN 1 ELSE 0 END AS admitted_in_period","CASE WHEN pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS out_in_period","CASE WHEN pi.out_vest_type = 3 THEN 1 ELSE 0 END AS died","CASE WHEN pi.out_vest_type = 3 AND pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS died_in_period","CASE WHEN (pi.out_vest_type IS NULL OR pi.out_vest_type <> 3) AND pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS survived_out_in_period","DATEDIFF(DAY, CASE WHEN pi.in_depart_time < :periodStart THEN :periodStart ELSE pi.in_depart_time END, CASE WHEN (pi.out_depart_time IS NULL OR pi.out_depart_time > :periodEnd) THEN :periodEnd ELSE pi.out_depart_time END) AS stay_days","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%术后%'' OR d.diag_name LIKE ''%手术后%'')) THEN 1 ELSE 0 END AS post_op","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info\" p2 WHERE p2.in_hospital_no = pi.in_hospital_no AND p2.id <> pi.id AND p2.del_flag = 0 AND p2.out_depart_time IS NOT NULL AND p2.out_depart_time < pi.in_depart_time AND DATEDIFF(HOUR, p2.out_de' || 'part_time, pi.in_depart_time) <= 48) THEN 1 ELSE 0 END AS readmit_48h"],"where":["pi.del_flag = 0","pi.in_depart_time IS NOT NULL","pi.in_depart_time < :periodEnd","(pi.out_depart_time IS NULL OR pi.out_depart_time >= :periodStart)"],"group":[],"note":"ICU 患者主表；床日按「本周期 ∩ 在院区间」取交集，跨月自动切分"}', '系统管理员', TIMESTAMP '2026-09-16 18:56:15');
