INSERT INTO "zing_doctor_db_prod"."quality_def_history" ("id", "def_type", "def_key", "expr_version", "change_type", "snapshot", "operator", "create_time") VALUES (178956652287200, 'FACT', 'fact_score_resource', NULL, 'UPDATE', '{"fact":"fact_score_resource","domain":"评分_资源","status":"ACTIVE","source":"apache2_score_record","alias":"a","patientKey":"patient_id","inHospitalNoKey":"in_hospital_no","patientNameKey":"patient_name","departKey":"depart_code","select":["a.patient_id AS patient_id","a.in_hospital_no AS in_hospital_no","a.patient_name AS patient_name","a.depart_code AS depart_code","a.total_score AS total_score","a.mortality_rate AS mortality_rate","a.score_time AS score_time","a.score_type AS score_type"],"derive":["CASE WHEN a.total_score >= 15 THEN 1 ELSE 0 END AS apache_ge15","(select p2.out_depart_time FROM \"zing_icu_db_prod\".\"patient_info\" p2 WHERE p2.id = a.patient_id)  AS out_depart_time"],"where":["a.status = 1","(select p2.out_depart_time FROM \"zing_icu_db_prod\".\"patient_info\" p2 WHERE p2.id = a.patient_id)  >= :periodStart","(select p2.out_depart_time FROM \"zing_icu_db_prod\".\"patient_info\" p2 WHERE p2.id = a.patient_id)  < :periodEnd"],"group":[],"note":"APACHE II 评分记录；预计病死率取 mortality_rate 均值"}', 'unknown', TIMESTAMP '2026-09-16 21:48:42');
