INSERT INTO "zing_doctor_db_prod"."quality_def_history" ("id", "def_type", "def_key", "expr_version", "change_type", "snapshot", "operator", "create_time") VALUES (178961132632300, 'FACT', 'fact_dvt', NULL, 'UPDATE', '{"fact":"fact_dvt","domain":"DVT预防","status":"ACTIVE","source":"patient_info","alias":"pi","patientKey":"patient_id","inHospitalNoKey":"in_hospital_no","patientNameKey":"patient_name","departKey":"depart_code","select":["pi.id AS patient_id","pi.in_hospital_no AS in_hospital_no","pi.name AS patient_name","pi.depart_code AS depart_code","pi.in_depart_time AS in_depart_time","pi.out_depart_time AS out_depart_time"],"derive":["CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%深静脉血栓%'' OR d.diag_name LIKE ''%下肢静脉血栓%'' OR d.diag_name LIKE ''%肺栓塞%'')) THEN 1 ELSE 0 END AS dvt_diag","CASE WHEN pi.out_vest_type = 3 AND EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%深静脉血栓%'' OR d.diag_name LIKE ''%下肢静脉血栓%'' OR d.diag_name LIKE ''%肺栓塞%'')) THEN 1 ELSE 0 END AS dvt_death","CASE WHEN pi.out_vest_type = 3 AND pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS died_in_period","CASE WHEN pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS out_in_period"],"where":["pi.del_flag = 0","pi.in_depart_time IS NOT NULL","pi.out_depart_time IS NOT NULL","pi.out_depart_time < :periodEnd","pi.out_depart_time >= :periodStart"],"group":[],"note":"DVT 由诊断文本识别；预防措施与滤器待接医嘱侧数据源"}', 'unknown', TIMESTAMP '2026-09-17 10:15:26');
