INSERT INTO "zing_doctor_db_prod"."quality_def_history" ("id", "def_type", "def_key", "expr_version", "change_type", "snapshot", "operator", "create_time") VALUES (178963438759300, 'FACT', 'fact_dvt', NULL, 'UPDATE', '{"fact":"fact_dvt","domain":"DVT预防","status":"ACTIVE","source":"patient_info","alias":"pi","patientKey":"patient_id","inHospitalNoKey":"in_hospital_no","patientNameKey":"patient_name","departKey":"depart_code","select":["pi.id AS patient_id","pi.in_hospital_no AS in_hospital_no","pi.name AS patient_name","pi.gender AS gender","pi.bed_code AS bed_code","pi.age AS age","pi.depart_code AS depart_code","pi.ward_name AS ward_name","pi.out_vest_type AS out_vest_type","pi.charge_doctor_name AS charge_doctor_name","pi.in_depart_time AS in_depart_time","pi.out_depart_time AS out_depart_time","pi.out_hospital_time AS out_hospital_time","CAST(pi.diagnosis_content AS VARCHAR(2000)) AS diagnosis_content"],"derive":["CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%深静脉血栓%'' OR d.diag_name LIKE ''%下肢静脉血栓%'' OR d.diag_name LIKE ''%肺栓塞%'')) THEN 1 ELSE 0 END AS dvt_diag","CASE WHEN pi.out_vest_type = 3 AND EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%深静脉血栓%'' OR d.diag_name LIKE ''%下肢静脉血栓%'' OR d.diag_name LIKE ''%肺栓塞%'')) THEN 1 ELSE 0 END AS dvt_death","CASE WHEN pi.out_vest_type = 3 AND pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS died_in_period","CASE WHEN pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS out_in_period","(SELECT e.drug_name FROM \"zing_icu_db_prod\".\"patient_advice_execute_drug\" e WHERE e.patient_id = pi.id AND (e.drug_name LIKE ''%肝素%'' OR e.drug_name LIKE ''%达比加群酯%'' OR e.drug_name LIKE ''%利伐沙班%'') limit 1)  AS dvt_drug","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice_execute_drug\" e WHERE e.patient_id = pi.id AND (e.drug_name LIKE ''%肝素%'' OR e.drug_name LIKE ''%达比加群酯%'' OR e.drug_name LIKE ''%利伐沙班%'')) THEN 1 ELSE' || ' 0 END AS dvt_drug_status","(SELECT o.advice_name FROM \"zing_icu_db_prod\".\"patient_advice_original\" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND (o.advice_name LIKE ''%气压治疗%'' OR o.advice_name LIKE ''%运动疗法%'' OR o.advice_name LIKE ''%弹力袜%'') limit 1)  AS dvt_active","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice_original\" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND (o.advice_name LIKE ''%气压治疗%'' OR o.advice_name LIKE ''%运动疗法%'' OR o.advice_name LIKE ''%弹力袜%'')) THEN 1 ELSE 0 END AS dvt_active_status","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice_original\" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND o.advice_name LIKE ''%下腔静脉滤器置入%'' )THEN 1 ELSE 0 END AS \"下腔静脉滤器置入\""],"where":["pi.del_flag = 0","pi.in_depart_time IS NOT NULL","pi.out_depart_time IS NOT NULL","pi.out_depart_time < :periodEnd","pi.out_depart_time >= :periodStart"],"group":[],"note":"DVT 由诊断文本识别；预防措施与滤器待接医嘱侧数据源"}', '系统管理员', TIMESTAMP '2026-09-17 16:39:47');
INSERT INTO "zing_doctor_db_prod"."quality_def_history" ("id", "def_type", "def_key", "expr_version", "change_type", "snapshot", "operator", "create_time") VALUES (178963446787600, 'METRIC', 'quality_408', 1, 'UPDATE', '{"code":"quality_408","name":"仅进行下腔静脉滤器置入的患者数","domain":"DVT预防","fact":"fact_dvt","unit":"人","valueType":"COUNT","calcMode":"DSL","implStatus":"IMPL","agg":"PT_COUNT","where":"dvt_drug_status = 0 AND dvt_active_status = 0","numerator":null,"denominatorWhere":null,"numeratorMetric":null,"denominatorMetric":null,"scale":100,"version":1,"dims":["depart_code"],"patientFields":[{"key":"patientName","label":null,"width":null},{"key":"bed_code","label":null,"width":null},{"key":"inHospitalNo","label":null,"width":null},{"key":"diagnosis_content","label":null,"width":null},{"key":"in_depart_time","label":null,"width":null},{"key":"out_depart_time","label":null,"width":null},{"key":"inNumerator","label":null,"width":null},{"key":"inDenominator","label":null,"width":null}],"categoryCode":null,"groupCode":null,"qualityTypeCode":null,"indexStandardCode":null,"amountShowType":null,"analysisCountType":null,"legacyScript":null,"legacySource":null,"newTarget":null,"reuseLevel":null,"remark":"待接下腔静脉滤器置入记录","sortNo":45,"derived":false}', '系统管理员', TIMESTAMP '2026-09-17 16:41:07');
INSERT INTO "zing_doctor_db_prod"."quality_def_history" ("id", "def_type", "def_key", "expr_version", "change_type", "snapshot", "operator", "create_time") VALUES (178963452802500, 'FACT', 'fact_dvt', NULL, 'UPDATE', '{"fact":"fact_dvt","domain":"DVT预防","status":"ACTIVE","source":"patient_info","alias":"pi","patientKey":"patient_id","inHospitalNoKey":"in_hospital_no","patientNameKey":"patient_name","departKey":"depart_code","select":["pi.id AS patient_id","pi.in_hospital_no AS in_hospital_no","pi.name AS patient_name","pi.gender AS gender","pi.bed_code AS bed_code","pi.age AS age","pi.depart_code AS depart_code","pi.ward_name AS ward_name","pi.out_vest_type AS out_vest_type","pi.charge_doctor_name AS charge_doctor_name","pi.in_depart_time AS in_depart_time","pi.out_depart_time AS out_depart_time","pi.out_hospital_time AS out_hospital_time","CAST(pi.diagnosis_content AS VARCHAR(2000)) AS diagnosis_content"],"derive":["CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%深静脉血栓%'' OR d.diag_name LIKE ''%下肢静脉血栓%'' OR d.diag_name LIKE ''%肺栓塞%'')) THEN 1 ELSE 0 END AS dvt_diag","CASE WHEN pi.out_vest_type = 3 AND EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%深静脉血栓%'' OR d.diag_name LIKE ''%下肢静脉血栓%'' OR d.diag_name LIKE ''%肺栓塞%'')) THEN 1 ELSE 0 END AS dvt_death","CASE WHEN pi.out_vest_type = 3 AND pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS died_in_period","CASE WHEN pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS out_in_period","(SELECT e.drug_name FROM \"zing_icu_db_prod\".\"patient_advice_execute_drug\" e WHERE e.patient_id = pi.id AND (e.drug_name LIKE ''%肝素%'' OR e.drug_name LIKE ''%达比加群酯%'' OR e.drug_name LIKE ''%利伐沙班%'') limit 1)  AS dvt_drug","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice_execute_drug\" e WHERE e.patient_id = pi.id AND (e.drug_name LIKE ''%肝素%'' OR e.drug_name LIKE ''%达比加群酯%'' OR e.drug_name LIKE ''%利伐沙班%'')) THEN 1 ELSE' || ' 0 END AS dvt_drug_status","(SELECT o.advice_name FROM \"zing_icu_db_prod\".\"patient_advice_original\" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND (o.advice_name LIKE ''%气压治疗%'' OR o.advice_name LIKE ''%运动疗法%'' OR o.advice_name LIKE ''%弹力袜%'') limit 1)  AS dvt_active","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice_original\" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND (o.advice_name LIKE ''%气压治疗%'' OR o.advice_name LIKE ''%运动疗法%'' OR o.advice_name LIKE ''%弹力袜%'')) THEN 1 ELSE 0 END AS dvt_active_status","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice_original\" o WHERE o.in_hospital_serial_no = pi.in_hospital_serial_no AND o.advice_name LIKE ''%下腔静脉滤器置入%'' )THEN 1 ELSE 0 END AS dvt_shu"],"where":["pi.del_flag = 0","pi.in_depart_time IS NOT NULL","pi.out_depart_time IS NOT NULL","pi.out_depart_time < :periodEnd","pi.out_depart_time >= :periodStart"],"group":[],"note":"DVT 由诊断文本识别；预防措施与滤器待接医嘱侧数据源"}', '系统管理员', TIMESTAMP '2026-09-17 16:42:08');
