INSERT INTO "zing_doctor_db_prod"."quality_def_history" ("id", "def_type", "def_key", "expr_version", "change_type", "snapshot", "operator", "create_time") VALUES (178963508406000, 'METRIC', 'quality_413', 1, 'UPDATE', '{"code":"quality_413","name":"进行深静脉血栓预防、诊断深静脉血栓并死亡的患者总数","domain":"DVT预防","fact":"fact_dvt","unit":"人","valueType":"COUNT","calcMode":"DSL","implStatus":"IMPL","agg":"PT_COUNT","where":"(dvt_active_status = 1) OR (dvt_drug_status = 1) OR (dvt_shu = 1)","numerator":"out_vest_type = 3 AND dvt_diag = 1","denominatorWhere":null,"numeratorMetric":null,"denominatorMetric":null,"scale":100,"version":1,"dims":["depart_code"],"patientFields":[{"key":"patientName","label":null,"width":null},{"key":"bed_code","label":null,"width":null},{"key":"inHospitalNo","label":null,"width":null},{"key":"diagnosis_content","label":null,"width":null},{"key":"in_depart_time","label":null,"width":null},{"key":"out_depart_time","label":null,"width":null},{"key":"inNumerator","label":null,"width":null},{"key":"inDenominator","label":null,"width":null}],"categoryCode":null,"groupCode":null,"qualityTypeCode":null,"indexStandardCode":null,"amountShowType":null,"analysisCountType":null,"legacyScript":null,"legacySource":null,"newTarget":null,"reuseLevel":null,"remark":"待接医嘱侧预防数据","sortNo":50,"derived":false}', '系统管理员', TIMESTAMP '2026-09-17 16:51:24');
INSERT INTO "zing_doctor_db_prod"."quality_def_history" ("id", "def_type", "def_key", "expr_version", "change_type", "snapshot", "operator", "create_time") VALUES (178963619672100, 'FACT', 'fact_staff', NULL, 'UPDATE', '{"fact":"fact_staff","domain":"职工_资源","status":"PENDING_SOURCE","source":"config_staff","alias":"s","patientKey":"user_id","inHospitalNoKey":"work_no","patientNameKey":"realname","departKey":"depart_name","select":["s.id AS user_id","s.realname AS realname","s.work_no AS work_no","s.depart_name AS depart_name"],"derive":["CASE WHEN s.post_name LIKE ''%医师%'' THEN 1 ELSE 0 END AS is_doctor","CASE WHEN s.post_name LIKE ''%护士%'' THEN 1 ELSE 0 END AS is_nurse"],"where":["s.del_flag = 0"],"group":[],"note":"待接 ICU 医护人员花名册（config_staff：科室 + 岗位）。口径确认后置 ACTIVE 即生效"}', '系统管理员', TIMESTAMP '2026-09-17 17:09:56');
INSERT INTO "zing_doctor_db_prod"."quality_def_history" ("id", "def_type", "def_key", "expr_version", "change_type", "snapshot", "operator", "create_time") VALUES (178963654966000, 'FACT', 'fact_assessment', NULL, 'UPDATE', '{"fact":"fact_assessment","domain":"评估依从","status":"ACTIVE","source":"patient_info","alias":"pi","patientKey":"patient_id","inHospitalNoKey":"in_hospital_no","patientNameKey":"patient_name","departKey":"depart_code","select":["pi.id AS patient_id","pi.in_hospital_no AS in_hospital_no","pi.name AS patient_name","pi.depart_code AS depart_code","pi.in_depart_time AS in_depart_time","pi.out_depart_time AS out_depart_time"],"derive":["CASE WHEN DATEDIFF(HOUR, pi.in_depart_time, CASE WHEN (pi.out_depart_time IS NULL OR pi.out_depart_time > :periodEnd) THEN :periodEnd ELSE pi.out_depart_time END) > 48 THEN 1 ELSE 0 END AS stay_gt_48h","CASE WHEN pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS out_in_period","CASE WHEN pi.out_vest_type = 3 AND pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS died_in_period","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_observe_module_item_record\" i WHERE i.patient_id = pi.id AND i.del_flag = 0 AND i.item_code = ''oi_ttpf'' and i.item_value is not null) THEN 1 ELSE 0 END AS sedation_assessed","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_observe_module_item_record\" i WHERE i.patient_id = pi.id AND i.del_flag = 0 AND i.item_code = ''oi_rass'' and i.item_value is not null) THEN 1 ELSE 0 END AS analgesia_assessed","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_observe_module_item\" i WHERE i.patient_id = pi.id AND i.del_flag = 0 AND (i.item_name LIKE ''%意识%'' OR i.item_name LIKE ''%格拉斯哥%'' OR i.item_name LIKE ''%GCS%'')) THEN 1 ELSE 0 END AS consciousness_assessed","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE ''%脑出血%'' OR d.diag_name LIKE ''%脑梗死%'' OR d.diag_name LIKE ''%颅脑损伤%'' OR d.diag_name LIKE ''%脑外伤%'' OR d.diag_name LIKE ''%蛛网膜下腔出血%'' OR d.diag_name LIKE ''%缺氧性脑病%'')) THEN 1 EL' || 'SE 0 END AS abi","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_advice\" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = ''1'' AND pa.start_time IS NOT NULL AND DATEDIFF(HOUR, pi.in_depart_time, pa.start_time) BETWEEN 0 AND 48 AND (pa.name LIKE ''%肠内营养%'' OR pa.name LIKE ''%鼻饲%'' OR pa.name LIKE ''%肠内%'' OR pa.name LIKE ''%能全力%'' OR pa.name LIKE ''%百普力%'' OR pa.name LIKE ''%瑞代%'' OR pa.name LIKE ''%瑞先%'')) THEN 1 ELSE 0 END AS en_48h"],"where":["pi.del_flag = 0","pi.in_depart_time IS NOT NULL","pi.in_depart_time < :periodEnd","(pi.out_depart_time IS NULL OR pi.out_depart_time >= :periodStart)"],"group":[],"note":"镇静/镇痛/意识评估与 48h 内肠内营养启动"}', '系统管理员', TIMESTAMP '2026-09-17 17:15:49');
INSERT INTO "zing_doctor_db_prod"."quality_def_history" ("id", "def_type", "def_key", "expr_version", "change_type", "snapshot", "operator", "create_time") VALUES (178963659862100, 'FACT', 'fact_assessment', NULL, 'UPDATE', '{"fact":"fact_assessment","domain":"评估依从","status":"ACTIVE","source":"patient_info","alias":"pi","patientKey":"patient_id","inHospitalNoKey":"in_hospital_no","patientNameKey":"patient_name","departKey":"depart_code","select":["pi.id AS patient_id","pi.in_hospital_no AS in_hospital_no","pi.name AS patient_name","pi.depart_code AS depart_code","pi.in_depart_time AS in_depart_time","pi.out_depart_time AS out_depart_time"],"derive":["CASE WHEN DATEDIFF(HOUR, pi.in_depart_time, CASE WHEN (pi.out_depart_time IS NULL OR pi.out_depart_time > :periodEnd) THEN :periodEnd ELSE pi.out_depart_time END) > 48 THEN 1 ELSE 0 END AS stay_gt_48h","CASE WHEN pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS out_in_period","CASE WHEN pi.out_vest_type = 3 AND pi.out_depart_time >= :periodStart AND pi.out_depart_time < :periodEnd THEN 1 ELSE 0 END AS died_in_period","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_observe_module_item_record\" i WHERE i.patient_id = pi.id AND i.del_flag = 0 AND i.item_code = ''oi_ttpf'' and i.item_value is not null) THEN 1 ELSE 0 END AS ttpf","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_observe_module_item_record\" i WHERE i.patient_id = pi.id AND i.del_flag = 0 AND i.item_code = ''oi_rass'' and i.item_value is not null) THEN 1 ELSE 0 END AS rass","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_observe_module_item\" i WHERE i.patient_id = pi.id AND i.del_flag = 0 AND (i.item_name LIKE ''%意识%'' OR i.item_name LIKE ''%格拉斯哥%'' OR i.item_name LIKE ''%GCS%'')) THEN 1 ELSE 0 END AS consciousness_assessed","CASE WHEN EXISTS (SELECT 1 FROM \"zing_icu_db_prod\".\"patient_info_diagnosis\" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AN